ы</option><option value="cloudpayments">CloudPayments — карты и СБП</option><option value="bank">Банк / СБП / перевод по своей ссылке</option><option value="payment_link">Другая платёжная ссылка</option></select></div><div class="field"><label>Твоя ссылка на оплату</label><input id="payment_url" placeholder="https://…" value="<?=htmlspecialchars((string)$p['payment_url'],ENT_QUOTES,'UTF-8')?>"></div><div class="provider" id="provider_hint"></div><p class="warn">На этом этапе Evruni не хранит реквизиты карты или банковского счёта. Вставь платёжную страницу своего аккаунта. Для автоматического подтверждения оплаты и мгновенного донат-алерта подключим webhook выбранного агрегатора.</p><h2 style="margin-top:24px">🎬 Оповещение на стриме</h2><div class="row"><div class="field"><label>Заголовок</label><input id="overlay_title" value="<?=htmlspecialchars((string)$p['overlay_title'],ENT_QUOTES,'UTF-8')?>"></div><div class="field"><label>Длительность, сек</label><input id="overlay_duration" type="number" min="3" max="30" value="<?=htmlspecialchars((string)$p['overlay_duration'],ENT_QUOTES,'UTF-8')?>"></div></div><div class="field"><label>Шаблон</label><input id="overlay_template" value="<?=htmlspecialchars((string)$p['overlay_template'],ENT_QUOTES,'UTF-8')?>"><small class="muted">Переменные: {name} {amount} {currency} {message}</small></div></section></div><button class="save" id="save">Сохранить настройки</button><div id="status" class="status"></div></div><script>const CSRF=<?=json_encode($csrf)?>;const ids=['title','description','currency','min_amount','max_amount','payment_method','payment_url','overlay_title','overlay_duration','overlay_template'];const hints={yookassa:'ЮKassa: создаёт платёж на стороне вашего магазина и поддерживает webhook payment.succeeded.',robokassa:'Robokassa: используйте свою платёжную форму/URL; ResultURL позволяет подтверждать успешную оплату.',cloudpayments:'CloudPayments: используйте свою платёжную страницу; уведомления о платеже приходят через callback/webhook.',bank:'Банк / СБП: вставьте собственную ссылку или страницу оплаты. Автоматическая проверка зависит от банка.',payment_link:'Любая HTTPS-ссылка на вашу платёжную страницу.'};function updateHint(){document.getElementById('provider_hint').textContent=hints[document.getElementById('payment_method').value]||''}document.getElementById('payment_method').onchange=updateHint;updateHint();document.getElementById('currency').value=<?=json_encode((string)$p['currency'])?>;document.getElementById('save').onclick=async()=>{const b={};ids.forEach(id=>b[id]=document.getElementById(id).value);const r=await fetch('/api/donation_profile.php',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':CSRF},body:JSON.stringify(b)});const d=await r.json();const s=document.getElementById('status');if(d.ok){document.getElementById('public_url').value=d.public_url;s.textContent='✓ Настройки сохранены';}else{s.textContent='Ошибка: '+(d.error||'неизвестная ошибка')}};document.getElementById('payment_method').value=<?=json_encode((string)$p['payment_method'])?>;updateHint();</script></body></html>
